templates.dataGenProvider:
package {{datagenPackageName}};

import java.nio.file.Path;
import java.util.concurrent.CompletableFuture;

import com.google.gson.JsonObject;

import net.minecraft.data.CachedOutput;
import net.minecraft.data.DataProvider;
import net.minecraft.data.PackOutput;

/**
 * Example data provider - generated by mcmodkit.
 *
 * It is the smallest useful provider: writing one JSON file into the mod's data pack when the data
 * run executes. Replace it with your own providers (recipes, models, tags, language, ...) or delete
 * it: the content mcmodkit generates from the spec already ships as plain JSON.
 */
public final class {{DATAGEN_PROVIDER_CLASS}} implements DataProvider {
	private final PackOutput output;

	public {{DATAGEN_PROVIDER_CLASS}}(PackOutput output) {
		this.output = output;
	}

	@Override
	public CompletableFuture<?> run(CachedOutput cache) {
		JsonObject json = new JsonObject();
		json.addProperty("generatedBy", "mcmodkit");
		json.addProperty("mod", "{{modId}}");
		Path path = this.output
			.getOutputFolder(PackOutput.Target.DATA_PACK)
			.resolve("{{namespace}}")
			.resolve("mcmodkit")
			.resolve("datagen.json");
		return DataProvider.saveStable(cache, json, path);
	}

	@Override
	public String getName() {
		return "{{modId}} example provider";
	}
}

templates.dataGenClass:
package {{datagenPackageName}};

import net.fabricmc.fabric.api.datagen.v1.DataGeneratorEntrypoint;
import net.fabricmc.fabric.api.datagen.v1.FabricDataGenerator;

/**
 * Data generation entry point - generated by mcmodkit.
 * Run it with ./gradlew runDatagen (output goes to src/main/generated).
 */
public final class {{DATAGEN_CLASS}} implements DataGeneratorEntrypoint {
	@Override
	public void onInitializeDataGenerator(FabricDataGenerator generator) {
		FabricDataGenerator.Pack pack = generator.createPack();
		// FabricDataGenerator.Pack also inherits DataGenerator.PackGenerator, so this method reference
		// needs an explicit target type; without the cast javac reports an ambiguous addProvider call.
		pack.addProvider((FabricDataGenerator.Pack.Factory<{{DATAGEN_PROVIDER_CLASS}}>) {{DATAGEN_PROVIDER_CLASS}}::new);
	}
}

templates.dataGenRunConfig:
// Data generation (mcmodkit): ./gradlew runDatagen
loom {
	runs {
		datagen {
			inherit client
			name "Data Generation"
			vmArg "-Dfabric-api.datagen"
			vmArg "-Dfabric-api.datagen.output-dir=${file('src/main/generated')}"
			vmArg "-Dfabric-api.datagen.modid={{modId}}"
			runDir "build/datagen"
		}
	}
}

sourceSets {
	main {
		resources { srcDir "src/main/generated" }
	}
}
